CREATE PROCEDURE [dbo].[sp_rpt_store_mgr_hours] AS /** ## Procedure Name       *[toast].[dbo].[sp_rpt_store_mgr_hours]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20260306   **Report Name**         *Sales and KPIs > Toast Company Restaurant Manager Shift Punches*   **Summary**   *A weekly list of the labor hours for Corporate store employees clocked in under Jobcode #10*      ### Parameters   ```sql   This report does not take any parameters ```      ### Output   *Shift DAte   POS Emp Num   Payroll ID   Manager Name   Clock In   Clock Out   Total Shift Hours*      ### Change History   **Change Date:**            *20200204*   **Author:**                 *Wilson, Don < dwilson@newks.com >*   **Version**:                2   **Change:**   *Add this header comment block*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;              declare          -- If this is for a table build, then Tab, if not, then Proc         @RunType varchar(4) = 'Proc'          -- The time the procedure begins running        ,@StartTime datetime = getdate()        -- The database the procedure is running in        ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself        ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error        ,@ErrorNumber int = 0        ,@ErrorMessage varchar(250) = ''        ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;          select * 		into #StoresIncluded 		from dev_aloha.dbo.get_StoresIncluded (9, 79, getdate())  		select  			c.WeekStart WeekStartDate, 			c.WeekEnd WeekEndDate, 			convert(date,hs.DateOfBusiness) ShiftDate, 			si.StoreID 'StoreNumber', 			si.StoreName 'Location',	 			e.ExternalEmployeeId 'PayrollID', 			e.First + ' ' + e.Last 'ManagerName', 			convert(varchar(8),cast(hs.ClockIn as time), 108) ClockIn, 			convert(varchar(8),cast(hs.ClockOut as time), 108) ClockOut, 			logging.dbo.Calc_Duration (hs.ClockIn, hs.ClockOut) TotalShiftHours 		from hstShift hs 		join #StoresIncluded si 		on hs.Store = si.StoreGUID 		join toast.dbo.Employees e 		on hs.Employee = e.GUID 		and si.StoreID = e.StoreID 		join dev_aloha.dbo.CalendarV2 c 		on hs.DateOfBusiness = c.Date 		where JobCode = '253c6715-5eee-42cf-811c-9b5124e41a42' 		and e.Deleted != 1 		and DateOfBusiness between DATEADD(wk,DATEDIFF(wk,7,GETDATE()),0) and DATEADD(wk,DATEDIFF(wk,7,GETDATE()),6) 		order by si.storeid, hs.DateOfBusiness, e.ExternalEmployeeId  		drop table #StoresIncluded 	            -- If the table build has no error, then commit the transaction         if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine;         THROW;     END CATCH END